primes = []
for candidate_num in range(2, 6000):
    is_prime_flag = True
    for prime_check in primes:
        if prime_check * prime_check > candidate_num:
            break
        if candidate_num % prime_check == 0:
            is_prime_flag = False
            break
    if is_prime_flag:
        primes.append(candidate_num)

def factorization(n):
    factors_dict = {}
    for prime in primes:
        if prime * prime > n:
            break
        if n % prime == 0:
            count = 0
            while n % prime == 0:
                n //= prime
                count += 1
            factors_dict[prime] = count
    if n > 1:
        factors_dict[n] = 1
    return factors_dict

def generate_all_factors(n):
    prime_factors = factorization(n)
    result_factors = [1]
    for prime in prime_factors:
        new_factors = []
        for val in result_factors:
            for exp in range(prime_factors[prime] + 1):
                new_factors.append(val * prime ** exp)
        result_factors = new_factors
    return result_factors

def calculate_f(n, m):
    f = {0: 0, 1: 1, 2: 2}
    for i in range(3, n + 1):
        f[i] = 2 * f[i - 1]
        for divisor in generate_all_factors(i):
            if 2 <= divisor <= i:
                f[i] += f[i // divisor] - f[(i - 1) // divisor]
                f[i] %= m
        f[i] %= m
    return f[n]

x_input, y_input = map(int, input().split())
print(calculate_f(x_input, y_input))
